# Row-by-row comparison of movesr with MOVES6 for every golden set used in the
# manuscript. Writes compact results to paper/data/.
#
# Environment:
#   MOVESR_DB         Parquet copy of the MOVES default database
#   DUCKDB            DuckDB command-line binary
#   MOVESR_REFERENCE  vein/inst/extdata/moves (Washtenaw golden set)
#   MOVES_WORK        directory with exports-dmv, exports-dmv-events,
#                     exports-dmv-evap24 (generated by data-raw/dmv/generate_dmv.py)
# Run from the movesr root:  Rscript paper/scripts/01_parity.R

suppressMessages(library(movesr))
library(data.table)
options(movesr.duckdb = Sys.getenv("DUCKDB", "duckdb"))
db <- movesr_database(Sys.getenv("MOVESR_DB"))
wash <- Sys.getenv("MOVESR_REFERENCE")
work <- Sys.getenv("MOVES_WORK")
out <- "paper/data"
dir.create(out, showWarnings = FALSE, recursive = TRUE)
set.seed(20261029)
timing <- list()
tic <- function() proc.time()[["elapsed"]]

# Relative difference with explicit handling of zeros.
pairs <- function(ref, mine, k, col, set, part) {
  m <- merge(ref[, c(k, col), with = FALSE], mine[, c(k, col), with = FALSE],
             by = k, all = TRUE, suffixes = c(".ref", ".mr"))
  setnames(m, paste0(col, c(".ref", ".mr")), c("ref", "mr"))
  m[, rel := fifelse(!is.na(ref) & !is.na(mr) & ref == 0 & mr == 0, 0, mr / ref - 1)]
  m[, `:=`(set = set, part = part)]
  m
}
summ <- function(m, by) {
  m[, .(rows_ref = sum(!is.na(ref)), rows_movesr = sum(!is.na(mr)),
        matched = sum(!is.na(ref) & !is.na(mr)),
        null_ref = sum(is.na(ref) & !is.na(mr)),
        missing = sum(!is.na(ref) & is.na(mr)),
        zero_both = sum(ref == 0 & mr == 0, na.rm = TRUE),
        median_abs = median(abs(rel), na.rm = TRUE),
        p99_abs = quantile(abs(rel), 0.99, na.rm = TRUE, names = FALSE),
        max_abs = max(abs(rel), na.rm = TRUE),
        gt_1e5 = sum(abs(rel) > 1e-5, na.rm = TRUE),
        gt_1e4 = sum(abs(rel) > 1e-4, na.rm = TRUE)), by = by]
}
keep <- list()
stats <- list()
sample_pairs <- function(m, n = 4000L) {
  m <- m[!is.na(ref) & !is.na(mr) & ref > 0]
  if (nrow(m) > n) m <- m[sample(.N, n)]
  m
}

# 1. Washtenaw County MI (vein golden set), running and start exhaust --------
met <- data.frame(hourID = 1:3, temperature = c(68, 50, 86), relHumidity = 50)
ref <- fread(file.path(wash, "rateperdistance.csv"))
t0 <- tic()
r <- movesr_running_rates(db, meteorology = met,
                          source_type_id = sort(unique(ref$sourceTypeID)),
                          road_type_id = unique(ref$roadTypeID))
timing$wash_running <- tic() - t0
k <- c("hourID", "sourceTypeID", "fuelTypeID", "modelYearID", "pollutantID",
       "roadTypeID", "avgSpeedBinID")
m <- pairs(ref, r, k, "ratePerDistance", "Washtenaw", "running")
m <- m[!is.na(ref)]
stats$wash_running <- summ(m, c("set", "part", "pollutantID"))
keep$wash_running <- m[, .(set, part, ref, mr, rel)]
ref <- fread(file.path(wash, "rateperstart.csv"))
t0 <- tic()
r <- movesr_start_rates(db, day_id = 2L, meteorology = met,
                        source_type_id = sort(unique(ref$sourceTypeID)))
timing$wash_start <- tic() - t0
k <- c("hourID", "sourceTypeID", "fuelTypeID", "modelYearID", "pollutantID")
m <- pairs(ref, r, k, "ratePerStart", "Washtenaw", "start")
m <- m[!is.na(ref)]
stats$wash_start <- summ(m, c("set", "part", "pollutantID"))
keep$wash_start <- m[, .(set, part, ref, mr, rel)]

# 2. DMV (DC 11001, Montgomery 24031, Fairfax 51059), July weekday 16-17 h ----
counties <- c(11001L, 24031L, 51059L)
pols <- c(1, 2, 3, 5, 6, 30, 31, 79, 80, 86, 87, 90, 91, 98, 100, 110, 111, 112,
          115, 118, 119)
refd <- fread(file.path(work, "exports-dmv", "rateperdistance.csv.gz"))
refd[, countyID := as.integer(linkID %/% 10000)]
t0 <- tic()
r <- movesr_region_rates(db, counties, process = c("running", "brake", "tire"),
                         month_id = 7, hour_id = 16:17, day_id = 5L,
                         road_type_id = 5, pollutant_id = pols)
timing$dmv_running_brake_tire <- tic() - t0
mine <- rbindlist(list(r$running, r$brake, r$tire), fill = TRUE)
k <- c("countyID", "hourID", "sourceTypeID", "fuelTypeID", "modelYearID",
       "pollutantID", "processID", "roadTypeID", "avgSpeedBinID")
m <- pairs(refd[processID %in% c(1, 9, 10)], mine, k, "ratePerDistance", "DMV", "distance")
m[, part := fifelse(processID == 1L, "running", "brake/tire")]
stats$dmv_distance <- summ(m, c("set", "part", "processID", "pollutantID"))
keep$dmv_distance <- m[, .(set, part, ref, mr, rel)]
rm(r, mine); gc()

refs <- fread(file.path(work, "exports-dmv-events", "rateperstart.csv.gz"))
refs[, countyID := as.integer(zoneID %/% 10)]
t0 <- tic()
r <- movesr_region_rates(db, counties, process = "start", month_id = 7,
                         hour_id = 16:17, day_id = 5L,
                         pollutant_id = sort(unique(refs$pollutantID)))$start
timing$dmv_start <- tic() - t0
k <- c("countyID", "hourID", "sourceTypeID", "fuelTypeID", "modelYearID", "pollutantID")
m <- pairs(refs, r, k, "ratePerStart", "DMV", "start")
stats$dmv_start <- summ(m, c("set", "part", "pollutantID"))
keep$dmv_start <- m[, .(set, part, ref, mr, rel)]

# 3. Evaporative, DMV 16-17 h: parked (per vehicle, per profile) and driving ---
ev_dir <- file.path(work, "exports-dmv-events")
rpv <- fread(file.path(ev_dir, "ratepervehicle.csv.gz"))[processID %in% 11:13]
rpp <- fread(file.path(ev_dir, "rateperprofile.csv.gz"))[processID == 12]
rpp[, zoneID := as.integer(temperatureProfileID %/% 10000)]
refd_ev <- refd[processID %in% 11:13]
tank_dmv <- list()
ttg_rows <- list()
for (cty in counties) {
  z <- cty * 10L
  met24 <- movesr_default_meteorology(db, cty, 7, 1:24)
  t0 <- tic()
  tank <- movesr_tank_temperature(db, met24$temperature, day_id = 5L)
  timing[[paste0("ttg_", cty)]] <- tic() - t0
  tank_dmv[[as.character(cty)]] <- tank
  t0 <- tic()
  x <- movesr_evap(db, cty, 2025, 7, 5L, hour_id = 16:17, meteorology = met24,
                   tank = tank, tvv_hours = 16:17, pollutant_id = c(1, 79, 80, 86, 87))
  timing[[paste0("evap_", cty)]] <- tic() - t0
  k <- c("hourID", "sourceTypeID", "fuelTypeID", "modelYearID", "pollutantID", "processID")
  m1 <- pairs(rpv[zoneID == z], x[processID %in% c(11L, 13L)], k, "ratePerVehicle",
              "DMV", "evap parked")
  m2 <- pairs(rpp[zoneID == z], x[processID == 12L], k, "ratePerVehicle",
              "DMV", "evap parked")
  er <- movesr_evap_running_rates(db, cty, 2025, 7, 5L, hour_id = 16:17,
                                  meteorology = met24, tank = tank,
                                  pollutant_id = c(1, 79, 80, 86, 87),
                                  e85_tank_properties = "e10")
  k2 <- c(k, "avgSpeedBinID")
  m3 <- pairs(refd_ev[countyID == cty], er, k2, "ratePerDistance", "DMV", "evap driving")
  m3 <- m3[!(is.na(ref) & is.na(mr))]
  ttg_rows[[length(ttg_rows) + 1L]] <- rbindlist(list(m1, m2, m3), fill = TRUE)[
    , countyID := cty]
}
m <- rbindlist(ttg_rows, fill = TRUE)
stats$dmv_evap <- summ(m, c("set", "part", "processID", "pollutantID"))
keep$dmv_evap <- m[, .(set, part, ref, mr, rel)]

# 4. Evaporative, DC 24 hours (dmv_evap24.mrs) ---------------------------------
e24 <- file.path(work, "exports-dmv-evap24")
ref24 <- rbind(fread(file.path(e24, "ratepervehicle.csv.gz")),
               fread(file.path(e24, "rateperprofile.csv.gz")), fill = TRUE)
met24 <- movesr_default_meteorology(db, 11001, 7, 1:24)
x24 <- movesr_evap(db, 11001, 2025, 7, 5L, meteorology = met24,
                   tank = tank_dmv[["11001"]], pollutant_id = c(1, 79, 80, 86, 87))
k <- c("hourID", "sourceTypeID", "fuelTypeID", "modelYearID", "pollutantID", "processID")
m <- pairs(ref24, x24, k, "ratePerVehicle", "DC 24 h", "evap parked")
stats$dc24 <- summ(m, c("set", "part", "processID", "pollutantID", "fuelTypeID"))
keep$dc24 <- m[, .(set, part, ref, mr, rel)]
fwrite(m[pollutantID == 1, .(hourID, sourceTypeID, fuelTypeID, modelYearID, processID,
                             ref, mr)], file.path(out, "dc24_thc_pairs.csv.gz"))

# 5. Intermediate tables (DC zone 110010) --------------------------------------
ex <- function(t) fread(file.path(ev_dir, paste0("exec_", t, ".csv.gz")))
tank <- tank_dmv[["11001"]]
att <- merge(ex("averagetanktemperature")[zoneID == 110010,
                                          .(hourDayID, tankTemperatureGroupID, opModeID,
                                            ref = averageTankTemperature)],
             tank$average_tank_temperature[, .(hourDayID, tankTemperatureGroupID, opModeID,
                                               mr = averageTankTemperature)],
             by = c("hourDayID", "tankTemperatureGroupID", "opModeID"), all = TRUE)
fwrite(att, file.path(out, "dc_tank_temperature.csv"))
saf <- merge(ex("soakactivityfraction")[zoneID == 110010,
                                        .(sourceTypeID, hourDayID, opModeID,
                                          ref = soakActivityFraction)],
             tank$soak_activity_fraction[, .(sourceTypeID, hourDayID, opModeID,
                                             mr = soakActivityFraction)],
             by = c("sourceTypeID", "hourDayID", "opModeID"), all = TRUE)
csi <- merge(ex("coldsoakinitialhourfraction")[zoneID == 110010,
                                               .(sourceTypeID, hourDayID, initialHourDayID,
                                                 ref = coldSoakInitialHourFraction)],
             tank$cold_soak_initial_hour_fraction[, .(sourceTypeID, hourDayID, initialHourDayID,
                                                      mr = coldSoakInitialHourFraction)],
             by = c("sourceTypeID", "hourDayID", "initialHourDayID"), all = TRUE)
cst <- merge(ex("coldsoaktanktemperature")[zoneID == 110010, .(hourID, ref = coldSoakTankTemperature)],
             tank$cold_soak[, .(hourID, mr = coldSoakTankTemperature)], by = "hourID")
act <- movesr_activity(db, 2025, 11001, 7, 5L)
x_exec <- function(t) fread(file.path(work, "movesr-testdata", "dmv-exec", paste0(t, ".csv.gz")))
inter <- rbindlist(list(
  att[, .(table = paste0("AverageTankTemperature, mode ", opModeID), n = .N,
          missing = sum(is.na(mr)), extra = sum(is.na(ref)),
          max_abs = max(abs(mr - ref), na.rm = TRUE), unit = "F"), by = opModeID][, !"opModeID"],
  cst[, .(table = "ColdSoakTankTemperature", n = .N, missing = 0L, extra = 0L,
          max_abs = max(abs(mr - ref)), unit = "F")],
  saf[, .(table = "SoakActivityFraction", n = .N, missing = sum(is.na(mr)),
          extra = sum(is.na(ref)), max_abs = max(abs(mr - ref), na.rm = TRUE), unit = "fraction")],
  csi[, .(table = "ColdSoakInitialHourFraction", n = .N, missing = sum(is.na(mr)),
          extra = sum(is.na(ref)), max_abs = max(abs(mr - ref), na.rm = TRUE), unit = "fraction")],
  {
    p <- merge(x_exec("sourcetypeagepopulation"), act$population,
               by = c("sourceTypeID", "ageID"))
    p[population.x > 0, .(table = "SourceTypeAgePopulation", n = .N, missing = 0L, extra = 0L,
                          max_abs = max(abs(population.y / population.x - 1)), unit = "relative")]
  },
  {
    s <- merge(x_exec("shobyageroadwayhour"),
               act$sho[, .(sourceTypeID, ageID, roadTypeID, hourID, mine = SHO)],
               by = c("sourceTypeID", "ageID", "roadTypeID", "hourID"))
    s[SHO > 0, .(table = "SHOByAgeRoadwayHour", n = .N, missing = 0L, extra = 0L,
                 max_abs = max(abs(mine / SHO - 1)), unit = "relative")]
  },
  {
    s <- merge(x_exec("shpbyagehour"),
               act$shp_by_age_hour[, .(sourceTypeID, ageID, hourID, mine = SHP)],
               by = c("sourceTypeID", "ageID", "hourID"))
    s[SHP > 0, .(table = "SHPByAgeHour", n = .N, missing = 0L, extra = 0L,
                 max_abs = max(abs(mine / SHP - 1)), unit = "relative")]
  }), use.names = TRUE)
fwrite(inter, file.path(out, "intermediate_tables.csv"))

# 6. Write results --------------------------------------------------------------
st <- rbindlist(stats, fill = TRUE)
fwrite(st, file.path(out, "parity_by_pollutant.csv"))
all <- rbindlist(keep, fill = TRUE)
overall <- summ(all, c("set", "part"))
fwrite(overall, file.path(out, "parity_overall.csv"))
# Distribution of |relative difference| (exact counts per decade) and a sample.
all[, decade := fifelse(rel == 0, -Inf, floor(log10(abs(rel))))]
fwrite(all[!is.na(rel), .N, by = .(set, part, decade)][order(set, part, decade)],
       file.path(out, "parity_decades.csv"))
fwrite(all[, sample_pairs(.SD), by = .(set, part)], file.path(out, "parity_sample.csv.gz"))
tm <- data.table(step = names(timing), seconds = unlist(timing))
fwrite(tm, file.path(out, "timing_movesr.csv"))
print(overall)
print(tm)
